  'gra-passive': [
    { oeuvre: 'condamne', q: 'Mets à la voix passive : « Le tribunal a condamné cet homme. »',
      opts: ['Cet homme a été condamné par le tribunal.', 'Cet homme est condamné le tribunal.', 'Le tribunal est condamné par cet homme.', 'On a condamné cet homme.'], ans: 0,
      exp: 'Le complément d’objet direct devient sujet, le verbe passe à « être » + participe passé, et l’ancien sujet devient complément d’agent introduit par « par ». Le temps du verbe ne change pas.' },
    { oeuvre: 'antigone', q: 'Dans « Polynice a été laissé sans sépulture », pourquoi n’y a-t-il pas de complément d’agent ?',
      opts: ['Il est volontairement effacé : on ne dit pas qui a décidé', 'Parce que la phrase est au passé composé', 'Parce que le sujet est un nom propre', 'Parce que le verbe est intransitif'], ans: 0,
      exp: 'C’est l’intérêt majeur du passif : il permet de supprimer l’agent. Ce qui devient alors une question d’examen : pourquoi le texte cache-t-il celui qui agit ?' },
    { oeuvre: 'condamne', q: 'Hugo écrit « la sentence fut exécutée » plutôt que « le bourreau tua l’homme ». Quel est l’effet ?',
      opts: ['La mise à mort devient une procédure sans responsable humain', 'La phrase devient plus rapide à lire', 'Cela rend la scène plus violente', 'Cela introduit un doute sur la culpabilité'], ans: 0,
      exp: 'Toute la dénonciation de Hugo tient dans cet écart. Le langage de la justice emploie le passif pour effacer la main qui frappe : nommer le passif, c’est dévoiler la stratégie.' },
    { oeuvre: 'boite', q: 'Quelle phrase ne peut PAS se mettre au passif ?',
      opts: ['L’enfant dormait.', 'L’enfant ouvrait la boîte.', 'La mère appela le voyant.', 'Le fqih punissait les élèves.'], ans: 0,
      exp: 'Seuls les verbes transitifs directs — ceux qui admettent un complément d’objet direct — ont un passif. « Dormir » est intransitif : il n’a rien à transformer en sujet.' },
    { oeuvre: 'antigone', q: 'Remets à l’actif : « Antigone a été arrêtée par les gardes. »',
      opts: ['Les gardes ont arrêté Antigone.', 'Antigone a arrêté les gardes.', 'On a arrêté les gardes.', 'Les gardes sont arrêtés par Antigone.'], ans: 0,
      exp: 'Le complément d’agent redevient sujet, le sujet redevient complément d’objet direct, et l’auxiliaire « être » disparaît. Attention à conserver le même temps.' },
  ],

  'gra-relief': [
    { oeuvre: 'antigone', q: 'Dans « C’est Créon qui a donné l’ordre », quel procédé est employé ?',
      opts: ['La mise en relief par « c’est… qui »', 'La voix passive', 'La négation restrictive', 'L’interrogation indirecte'], ans: 0,
      exp: '« C’est… qui » encadre le sujet pour le détacher ; « c’est… que » encadre un complément. C’est le procédé d’emphase le plus courant.' },
    { oeuvre: 'boite', q: 'Dans « Cette boîte, il ne s’en séparait jamais », comment l’élément est-il mis en relief ?',
      opts: ['Par dislocation : le groupe est détaché en tête et repris par un pronom', 'Par une tournure passive', 'Par une subordonnée relative', 'Par une comparaison'], ans: 0,
      exp: 'La dislocation détache un groupe en tête ou en fin de phrase, et le reprend par un pronom (« en », « le », « y »). Très fréquente à l’oral, elle marque à l’écrit une forte insistance.' },
    { oeuvre: 'condamne', q: 'Quelle différence entre mise en relief et voix passive ?',
      opts: ['L’emphase détache un élément sans changer les fonctions ; le passif réorganise sujet et complément', 'Le passif est toujours emphatique', 'La mise en relief exige le subjonctif', 'Aucune différence'], ans: 0,
      exp: 'Piège fréquent. Dans « c’est le tribunal qui a condamné », le tribunal reste sujet : c’est de l’emphase. Dans « il a été condamné par le tribunal », les fonctions ont changé : c’est un passif.' },
    { oeuvre: 'antigone', q: 'Antigone répète « c’est moi qui » à plusieurs reprises devant Créon. Que traduit cette insistance ?',
      opts: ['Elle revendique seule son acte et refuse de partager la faute', 'Elle cherche à impliquer Ismène', 'Elle exprime un doute sur ce qu’elle a fait', 'Elle demande la clémence du roi'], ans: 0,
      exp: 'La mise en relief place le « je » au centre et l’y maintient. Grammaticalement, elle assume ; dramatiquement, elle coupe toute issue — Créon ne peut plus étouffer l’affaire.' },
    { oeuvre: 'boite', q: 'Mets en relief le complément : « L’enfant aimait le silence du matin. »',
      opts: ['C’est le silence du matin que l’enfant aimait.', 'C’est l’enfant qui aimait le silence du matin.', 'Le silence du matin était aimé de l’enfant.', 'L’enfant, il aimait le silence du matin.'], ans: 0,
      exp: 'Pour un complément d’objet, on emploie « c’est… que ». La deuxième réponse met en relief le sujet, la troisième est un passif, la quatrième disloque le sujet.' },
  ],

  'gra-negation': [
    { oeuvre: 'condamne', q: 'Dans « Je ne vois plus le jour », quels mots forment la négation ?',
      opts: ['« ne » et « plus »', '« ne » seulement', '« plus » seulement', '« vois » et « plus »'], ans: 0,
      exp: 'La négation française est en deux parties encadrant le verbe : ne… pas, ne… plus, ne… jamais, ne… rien, ne… personne, ne… aucun. À l’écrit, le « ne » ne se supprime jamais.' },
    { oeuvre: 'antigone', q: 'Que signifie « Je n’ai que ma vie à donner » ?',
      opts: ['Je n’ai rien d’autre que ma vie : c’est une restriction, pas une négation', 'Je n’ai pas de vie à donner', 'Je refuse de donner ma vie', 'Je possède beaucoup de choses'], ans: 0,
      exp: '« Ne… que » ne nie pas : il restreint, et équivaut à « seulement ». Confondre restriction et négation inverse complètement le sens de la phrase — erreur classique en compréhension.' },
    { oeuvre: 'boite', q: 'Quelle phrase contient une négation totale ?',
      opts: ['Il ne comprenait rien.', 'Il ne comprenait que les mots simples.', 'Il comprenait à peine.', 'Il comprenait peu de choses.'], ans: 0,
      exp: 'La négation totale porte sur toute la phrase (ne… rien, ne… jamais, ne… personne). La deuxième est une restriction ; les deux dernières atténuent sans nier.' },
    { oeuvre: 'antigone', q: 'Le personnage d’Antigone est construit sur le mot « non ». Que produit l’accumulation des tournures négatives dans ses répliques ?',
      opts: ['Elle se définit par ce qu’elle refuse, jamais par ce qu’elle veut', 'Elle exprime une tristesse passagère', 'Elle cherche à convaincre Créon par la logique', 'Elle atténue la portée de son acte'], ans: 0,
      exp: 'C’est l’observation qui vaut des points : une héroïne du refus se reconnaît d’abord dans sa syntaxe. Elle ne propose pas un autre monde, elle rejette celui qu’on lui offre.' },
    { oeuvre: 'condamne', q: 'Transforme en restriction : « Il pensait uniquement à sa fille. »',
      opts: ['Il ne pensait qu’à sa fille.', 'Il ne pensait pas à sa fille.', 'Il ne pensait jamais à sa fille.', 'Il ne pensait rien à sa fille.'], ans: 0,
      exp: '« Uniquement » et « seulement » se rendent par « ne… que ». Les trois autres réponses nient, ce qui dit exactement le contraire.' },
  ],

